look.customCSS:
/* ───── 巴黎留白 · 第一批 ───── */
[data-wk="chat"]{background:#FAF8F4 !important}
[data-wk="chat"] *{font-family:"Didot","Bodoni 72","Playfair Display","Songti SC","Noto Serif SC",Georgia,serif !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：象牙白，名字是细衬线，底下一根发丝线 */
[data-wk="chathead"]{background:#FAF8F4 !important;border-bottom:none !important;box-shadow:0 1px 0 #D8D4CD !important;gap:6px !important}
[data-wk="headink"],[data-wk="headink"] *{color:#1E1D1B !important}
[data-wk="headname"] > [data-wk="headink"]{font-weight:400 !important;letter-spacing:.2em !important}
[data-wk="headdim"]{color:#B5B0A8 !important;white-space:nowrap !important;letter-spacing:.15em !important}
[data-wk="chatback"],[data-wk="chatback"] *{color:#1E1D1B !important}
[data-wk="chatback"] svg,[data-wk="headdim"] svg{stroke:#1E1D1B !important;stroke-width:1.2 !important}
[data-wk="chathead"] [data-wk="headink"] > [data-wk="headdim"]{display:none !important}
[data-wk="chathead"] [data-wk="headname"],[data-wk="chathead"] button:has(> [data-wk="headname"]){flex:1 1 auto !important;min-width:0 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{flex:none !important;width:32px !important;min-width:32px !important;height:32px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chathead"] + *:not([data-wk="body"]){margin-top:4px !important}

/* 头像：两圈细线，像信封上一枚圆邮戳 */
button[data-wk="avatar"],span[data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #FAF8F4,0 0 0 4px #1E1D1B,0 0 0 7px #FAF8F4,0 0 0 7.6px #D8D4CD !important}
button[data-wk="avatar"] > *,span[data-wk="avatar"] > *,img[data-wk="avatar"]{border-radius:50% !important;filter:grayscale(.15) !important}
[data-wk="chathead"] img[data-wk="avatar"]{box-shadow:0 0 0 2px #FAF8F4,0 0 0 3px #1E1D1B !important}

/* 气泡：他的白卡描发丝线；我的浅灰纸；都不带尾巴，左下（他）/右下（我）一个小直角 */
[data-wk="bubble"][data-kind="text"]{border:none !important;letter-spacing:.1em !important;padding:12px 20px !important;color:#1E1D1B !important;font-size:14.5px !important;line-height:1.75 !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:#FFFFFF !important;border-radius:6px 6px 6px 1px !important;box-shadow:0 0 0 .8px #D8D4CD,0 3px 10px rgba(30,29,27,.05) !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#EFEDE9 !important;border-radius:6px 6px 1px 6px !important;box-shadow:none !important}

/* 时间：两侧一根细线，线头一颗菱形，中间斜体小字 */
[data-wk="time"]{display:flex !important;justify-content:center !important}
[data-wk="time"] > span{display:inline-flex !important;align-items:center !important;gap:10px !important;background:transparent !important;border:none !important;box-shadow:none !important;color:#8A857D !important;font:italic 400 12px/1 Georgia,"Times New Roman",serif !important;letter-spacing:.12em !important;padding:0 !important}
[data-wk="time"] > span::before,[data-wk="time"] > span::after{content:"" !important;width:74px !important;height:8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PHBhdGggZD0nTTUgLjggTDkuMiA1IEw1IDkuMiBMLjggNVonIGZpbGw9JyMxRTFEMUInLz48L3N2Zz4=") right center/7px 7px no-repeat,linear-gradient(#1E1D1B,#1E1D1B) left center/calc(100% - 9px) .8px no-repeat !important}
[data-wk="time"] > span::after{transform:scaleX(-1) !important}

/* 已读＝斜体「lu」配实心小点；已送达＝「envoyé」配空心小点 */
[data-wk="meta"]{display:inline-flex !important;align-items:center !important;gap:8px !important;font-size:0 !important;color:#8A857D !important}
[data-wk="meta"] *{display:none !important}
[data-wk="meta"]::before{content:"envoyé" !important;font:italic 400 12px/1 Georgia,"Times New Roman",serif !important;letter-spacing:.06em !important;color:#8A857D !important}
[data-wk="meta"][data-read="1"]::before{content:"lu" !important}
[data-wk="meta"]::after{content:"" !important;width:8px !important;height:8px !important;flex:none !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nbm9uZScgc3Ryb2tlPScjMUUxRDFCJyBzdHJva2Utd2lkdGg9JzEuMScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="meta"][data-read="1"]::after{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PGNpcmNsZSBjeD0nNScgY3k9JzUnIHI9JzMuMicgZmlsbD0nIzFFMUQxQicgc3Ryb2tlPScjMUUxRDFCJyBzdHJva2Utd2lkdGg9JzEuMScvPjwvc3ZnPg==") center/contain no-repeat !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-wk="bubble"][data-kind="typing"]{background:#FFFFFF !important;border:none !important;border-radius:6px 6px 6px 1px !important;box-shadow:0 0 0 .8px #D8D4CD !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#1E1D1B !important;width:4px !important;height:4px !important}
[data-wk="name"]{color:#8A857D !important;font-style:italic !important}

/* 动描：用 « » 括起来的一句斜体，居中，不进框 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:block !important;background:transparent !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#8A857D !important;font-style:italic !important;font-size:13px !important;line-height:1.9 !important;letter-spacing:.08em !important;text-align:center !important;padding:4px 18px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"« " !important;color:#1E1D1B !important;font-style:normal !important}
[data-wk="narrink"]::after,[data-wk="myactink"]::after{content:" »" !important;color:#1E1D1B !important;font-style:normal !important}
[data-wk="myactink"]{text-align:right !important}
[data-wk="narrbar"]{background:#FAF8F4 !important;border-top:.8px solid #D8D4CD !important}
[data-wk="narrkind"]{border:.8px solid #D8D4CD !important;border-radius:2px !important;background:transparent !important;color:#8A857D !important}
[data-wk="narrkind"][data-on="1"]{background:#1E1D1B !important;border-color:#1E1D1B !important;color:#FAF8F4 !important}
/* 系统提示：一行小号字，前后各一段细线 */
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{display:inline-block !important;background:linear-gradient(#D8D4CD,#D8D4CD) left center/14px .8px no-repeat,linear-gradient(#D8D4CD,#D8D4CD) right center/14px .8px no-repeat !important;border:none !important;color:#8A857D !important;font-size:11px !important;font-style:normal !important;letter-spacing:.14em !important;padding:0 22px !important}
[data-wk="sysnoteclose"]{color:#B5B0A8 !important}

/* 底栏：象牙白，上沿一根细线；输入框只是一道下划线；最右「让他回复」是黑色圆钮 */
[data-wk="composer"]{background:#FAF8F4 !important;border-top:none !important;box-shadow:0 -1px 0 #D8D4CD !important;align-items:center !important;gap:10px !important}
[data-wk="chatinput"]{background:transparent !important;border:none !important;border-bottom:1px solid #1E1D1B !important;border-radius:0 !important;color:#1E1D1B !important;letter-spacing:.08em !important;padding-left:2px !important;padding-right:2px !important}
[data-wk="chatinput"]::placeholder{color:#B5B0A8 !important;font-style:italic !important}
[data-wk="chatplus"],[data-wk="send"],[data-wk="chatreply"]{border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{width:30px !important;min-width:30px !important;height:30px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCA0MCA0MCc+PHBhdGggZD0nTTIwIDEyIFYyOCBNMTIgMjAgSDI4JyBzdHJva2U9JyMxRTFEMUInIHN0cm9rZS13aWR0aD0nMS4yJyBzdHJva2UtbGluZWNhcD0ncm91bmQnLz48L3N2Zz4=") center/contain no-repeat !important}
[data-wk="send"]{width:32px !important;min-width:32px !important;height:32px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:42px !important;min-width:42px !important;height:42px !important;border-radius:50% !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
[data-wk="chatpanel"]{background:#FAF8F4 !important;border-top:.8px solid #D8D4CD !important}
[data-wk="quotedraft"]{position:relative !important;z-index:3 !important}
/* 每个人每一串的第一句上面，一行小小的法语 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]{margin-top:20px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"]::before{content:"Mon petit bonheur" !important;position:absolute !important;bottom:100% !important;margin-bottom:4px !important;white-space:nowrap !important;font:italic 400 11px/1 Georgia,"Times New Roman",serif !important;letter-spacing:.1em !important;color:#8A857D !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{left:2px !important;content:"Je pense à toi" !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="1"]::before{right:2px !important}
/* ───── 巴黎留白 · 第二批：卡片 ───── */
[data-wk="voice"],[data-wk="wxcard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"]{background:#fff !important;border:none !important;border-radius:4px !important;box-shadow:0 0 0 .8px #D8D4CD,0 4px 14px rgba(30,29,27,.06) !important;color:#1E1D1B !important}
[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *{color:#1E1D1B !important;border-color:#D8D4CD !important}

/* 转账＝一封信：白信封、暗红蜡封，金额像信上写的数；收下了信封打开露出信纸，退回了蜡封变灰 */
[data-wk="transfercard"]{position:relative !important;background:#fff !important;border:none !important;border-radius:4px !important;box-shadow:0 0 0 .8px #D8D4CD,0 4px 14px rgba(30,29,27,.06) !important;color:#1E1D1B !important;padding-left:76px !important}
[data-wk="transfercard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:54px !important;height:40px !important;margin-top:-24px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"] *{color:#1E1D1B !important;border-color:#D8D4CD !important}
[data-wk="transferlabel"]{color:#8A857D !important;font-style:italic !important;letter-spacing:.15em !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#1E1D1B !important;font-weight:400 !important;letter-spacing:.04em !important}
[data-wk="transferrule"]{border:none !important;height:8px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMCAxMCc+PHBhdGggZD0nTTUgLjggTDkuMiA1IEw1IDkuMiBMLjggNVonIGZpbGw9JyMxRTFEMUInLz48L3N2Zz4=") center/6px 6px no-repeat,linear-gradient(90deg,transparent,#1E1D1B 30%,#1E1D1B calc(50% - 8px),transparent calc(50% - 8px),transparent calc(50% + 8px),#1E1D1B calc(50% + 8px),#1E1D1B 70%,transparent) center/100% .8px no-repeat !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:#FAF8F4 !important}
[data-wk="transferbtn"]{border-radius:2px !important;letter-spacing:.15em !important}
[data-wk="transferbtn"][data-part="take"]{background:#1E1D1B !important;color:#FAF8F4 !important;border:none !important}
[data-wk="transferbtn"][data-part="back"]{background:transparent !important;color:#1E1D1B !important;border:.8px solid #1E1D1B !important}
[data-wk="transferseal"]{background:transparent !important;border:.8px solid #1E1D1B !important;color:#1E1D1B !important;border-radius:50% !important;box-shadow:none !important;font-style:italic !important}
[data-wk="transfercard"][data-status="accepted"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.65 !important}

/* 红包＝一杯冒着热气的拿铁；领完了杯子空了 */
[data-wk="rpcard"]{position:relative !important;width:220px !important;min-height:80px !important;padding:16px 16px 16px 82px !important;background:#fff !important;border:none !important;border-radius:4px !important;box-shadow:0 0 0 .8px #D8D4CD,0 4px 14px rgba(30,29,27,.06) !important;color:#1E1D1B !important}
[data-wk="rpcard"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:58px !important;height:48px !important;margin-top:-26px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpcard"]::after{content:"un café" !important;position:absolute !important;right:12px !important;bottom:6px !important;font:italic 400 10.5px/1 Georgia,serif !important;letter-spacing:.12em !important;color:#8A857D !important}
[data-wk="rpcard"] *{color:#1E1D1B !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"] > div:not([data-wk]){padding:0 !important;background:transparent !important}
[data-wk="rpmsg"]{-webkit-line-clamp:2 !important}
[data-wk="rpcard"][data-status="done"]::before{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="rpcard"][data-status="done"]::after{content:"merci" !important}
/* 拆红包：关着是一封合上的信，「开」是那枚暗红蜡封；拆开后是一张摊开的信纸，金额写在信上，底下一行签名 */
[data-wk="rpenvelope"]{position:relative !important;overflow:visible !important}
[data-wk="rpenvelope"][data-stage="closed"]{background:linear-gradient(155deg,transparent 49.6%,#1E1D1B 49.8%,#1E1D1B 50.2%,transparent 50.4%) left top/50% 46% no-repeat,linear-gradient(205deg,transparent 49.6%,#1E1D1B 49.8%,#1E1D1B 50.2%,transparent 50.4%) right top/50% 46% no-repeat,#fff !important;border:none !important;border-radius:3px !important;box-shadow:0 0 0 .8px #D8D4CD,0 18px 40px rgba(30,29,27,.18) !important}
[data-wk="rpenvelope"][data-stage="closed"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="closed"] *{color:#1E1D1B !important}
[data-wk="rpopenbtn"]{background:radial-gradient(circle at 42% 38%,#A83A3A,#8C2A2A 60%,#6E1E1E) !important;border:none !important;border-radius:50% !important;box-shadow:0 0 0 3px rgba(140,42,42,.25),0 3px 6px rgba(0,0,0,.25) !important}
[data-wk="rpopenbtn"],[data-wk="rpopenbtn"] *{color:transparent !important;font-size:0 !important}
[data-wk="rpenvelope"][data-stage="open"]{background:repeating-linear-gradient(180deg,transparent 0 27px,#D8D4CD 27px 28px) 0 80px/100% calc(100% - 120px) no-repeat,#FAF8F4 !important;border:none !important;border-radius:2px !important;box-shadow:0 0 0 .8px #D8D4CD,0 18px 40px rgba(30,29,27,.18) !important}
[data-wk="rpenvelope"][data-stage="open"]::after{content:"— avec amour" !important;position:absolute !important;right:22px !important;bottom:18px !important;font:italic 400 13px/1 Georgia,serif !important;letter-spacing:.1em !important;color:#8A857D !important}
[data-wk="rpenvelope"][data-stage="open"] [data-wk="rparc"]{display:none !important}
[data-wk="rpenvelope"][data-stage="open"] *{color:#1E1D1B !important}
[data-wk="rpavatar"]{border-radius:50% !important;box-shadow:0 0 0 3px #fff,0 0 0 4px #1E1D1B !important}
[data-wk="rpamount"]{color:#1E1D1B !important;background:none !important;font-weight:400 !important}
[data-wk="rpclose"]{background:#fff !important;border:.8px solid #1E1D1B !important;color:#1E1D1B !important}

/* 照片：一张白边相片，右下角贴一枚巴黎窗邮票 */
[data-wk="photocard"]{position:relative !important;overflow:visible !important;background:#fff !important;border:none !important;border-radius:2px !important;padding:8px 8px 26px !important;box-shadow:0 0 0 .8px #D8D4CD,0 6px 16px rgba(30,29,27,.08) !important}
[data-wk="photocard"]::after{content:"" !important;position:absolute !important;right:-10px !important;bottom:-14px !important;width:30px !important;height:35px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;transform:rotate(6deg) !important}
[data-wk="photoface"]{background:#EFEDE9 !important;border:none !important;border-radius:1px !important}
[data-wk="photoface"] *,[data-wk="phototext"]{color:#1E1D1B !important}
[data-wk="photocap"],[data-wk="photohint"]{color:#8A857D !important;font-style:italic !important}

/* 语音：白卡，前面一颗细圈播放三角，波纹是墨线 */
[data-wk="voice"] > *{background:transparent !important;box-shadow:none !important;border:none !important;color:#1E1D1B !important}
[data-wk="voice"][data-me]{padding:0 14px 0 34px !important;position:relative !important;border-radius:4px !important}
[data-wk="voice"]::before{content:"" !important;position:absolute !important;left:12px !important;top:50% !important;width:14px !important;height:14px !important;margin-top:-7px !important;background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxNCAxNCc+PGNpcmNsZSBjeD0nNycgY3k9JzcnIHI9JzYnIGZpbGw9J25vbmUnIHN0cm9rZT0nIzFFMUQxQicgc3Ryb2tlLXdpZHRoPScuOScvPjxwYXRoIGQ9J001LjYgNC40IEw5LjYgNyBMNS42IDkuNlonIGZpbGw9JyMxRTFEMUInLz48L3N2Zz4=") center/contain no-repeat !important;z-index:2 !important}
[data-wk="voice"][data-me="1"]{background:#EFEDE9 !important;box-shadow:none !important}
[data-wk="voicewave"] span{background:#1E1D1B !important}

[data-wk="wxcardsky"]{background:#EFEDE9 !important}
[data-wk="wxcardsky"] *{color:#1E1D1B !important}
[data-wk="wxcardsky"] svg{stroke:#1E1D1B !important}
[data-wk="wxcardsay"]{background:#fff !important;color:#1E1D1B !important;border-top:.8px solid #D8D4CD !important;font-style:italic !important}
[data-wk="geopin"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyMCAzMCc+PHBhdGggZD0nTTEwIDEgQzUgMSAyIDUgMiA5IEMyIDE1IDEwIDI4IDEwIDI4IEMxMCAyOCAxOCAxNSAxOCA5IEMxOCA1IDE1IDEgMTAgMVonIGZpbGw9JyMxRTFEMUInLz48Y2lyY2xlIGN4PScxMCcgY3k9JzknIHI9JzMnIGZpbGw9JyNGQUY4RjQnLz48L3N2Zz4=") center/contain no-repeat !important;box-shadow:none !important;border:none !important;width:18px !important;height:27px !important;border-radius:0 !important}
[data-wk="geopin"] *{opacity:0 !important}
[data-wk="geopinstem"]{background:#1E1D1B !important}
[data-wk="namecard"] img{border-radius:50% !important;box-shadow:0 0 0 2px #fff,0 0 0 3px #1E1D1B !important}

/* 拍一拍、通话结束：一行小字，前后细线 */
